diff --git a/test/server.test.js b/test/server.test.js
index f75a584..27d48dc 100644
--- a/test/server.test.js
+++ b/test/server.test.js
@@ -29,3 +29,33 @@ test('POST /cart/quote', async () => {
   assert.equal(res.status, 200)
   assert.equal(res.body.totalCents, 3239)
 })
+
+test('GET /books with author filter (case-insensitive substring)', async () => {
+  const res = await app()({ method: 'GET', url: '/books?author=martin' })
+  assert.equal(res.status, 200)
+  // All returned books should have author containing 'martin' (case-insensitive)
+  for (const b of res.body) {
+    assert.ok(String(b.author).toLowerCase().includes('martin'))
+  }
+  // Expect at least one known Martin author book
+  const titles = res.body.map((b) => b.title)
+  assert.ok(titles.includes('Clean Code'))
+})
+
+test('GET /books with tag filter', async () => {
+  const res = await app()({ method: 'GET', url: '/books?tag=craft' })
+  assert.equal(res.status, 200)
+  // All returned books must have the exact tag craft
+  for (const b of res.body) {
+    assert.ok(Array.isArray(b.tags) && b.tags.includes('craft'))
+  }
+})
+
+test('GET /books with combined author and tag filters', async () => {
+  const res = await app()({ method: 'GET', url: '/books?author=martin&tag=craft' })
+  assert.equal(res.status, 200)
+  for (const b of res.body) {
+    assert.ok(String(b.author).toLowerCase().includes('martin'))
+    assert.ok(Array.isArray(b.tags) && b.tags.includes('craft'))
+  }
+})
